-- Moments: core D1 schema (SQLite), translated from the Supabase/Postgres schema.
--
-- Notes on the Postgres -> SQLite translation:
--   * All ids are TEXT. Users are keyed by their Clerk user id (e.g. "user_2abc...");
--     every other id is generated by the Worker via crypto.randomUUID() before INSERT
--     -- SQLite has no gen_random_uuid(), so there is no DEFAULT on id columns.
--   * Postgres ENUMs -> TEXT + CHECK constraint.
--   * TIMESTAMPTZ -> TEXT, ISO 8601 (sortable, UTC), defaulting to the current time.
--   * BOOLEAN -> INTEGER 0/1 (SQLite has no native boolean).
--   * JSONB -> TEXT holding a JSON string; read/write JSON in Worker code.
--   * There is no Postgres RLS equivalent here -- every access rule that used to live in
--     a CREATE POLICY must be enforced in the Worker route handler instead.
--
-- Scope: this migration ports the core tables (identity, relationships, moments, chat,
-- mood, calendar, journal, notifications, streak/wrapped summaries, activities/games).
-- NOT yet ported (left on Postgres for now, pending their own migration): the watch-party
-- suite (watch_sessions, user_streaming_connections, watch_watchlist, watch_history,
-- watch_messages), quiz_live_sessions, shared_album_items, streak_active_days,
-- notification_dedup, and edge_rate_limits -- their exact current schema wasn't
-- re-verified before writing this migration, so they're deferred rather than guessed at.

PRAGMA foreign_keys = ON;

-- Users (identity now lives in Clerk; this is the app-owned profile row, keyed by Clerk's user id)
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT,
  avatar_url TEXT,
  expo_push_token TEXT,
  expo_push_token_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Relationships
CREATE TABLE relationships (
  id TEXT PRIMARY KEY,
  user_1_id TEXT NOT NULL REFERENCES users(id),
  user_2_id TEXT REFERENCES users(id),
  relationship_name TEXT DEFAULT 'Our Moments',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'ended')),
  streak_count INTEGER NOT NULL DEFAULT 0,
  invite_code TEXT UNIQUE,
  distance_mode INTEGER NOT NULL DEFAULT 0,
  subscription_tier TEXT NOT NULL DEFAULT 'free' CHECK (subscription_tier IN ('free', 'plus')),
  subscription_owner_id TEXT REFERENCES users(id),
  anniversary_date TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_relationships_user1 ON relationships(user_1_id);
CREATE INDEX idx_relationships_user2 ON relationships(user_2_id);
CREATE INDEX idx_relationships_invite ON relationships(invite_code);

-- Moments
CREATE TABLE moments (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  type TEXT NOT NULL CHECK (type IN ('photo', 'text', 'voice', 'mood', 'location')),
  content TEXT,
  media_url TEXT,
  mood TEXT CHECK (mood IN ('happy', 'excited', 'calm', 'stressed', 'lonely')),
  reactions TEXT NOT NULL DEFAULT '{}',
  viewed_by TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_moments_relationship ON moments(relationship_id);
CREATE INDEX idx_moments_created_at ON moments(created_at DESC);

-- Messages
CREATE TABLE messages (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  sender_id TEXT NOT NULL REFERENCES users(id),
  content TEXT,
  media_url TEXT,
  media_type TEXT CHECK (media_type IN ('image', 'voice', 'video')),
  reactions TEXT NOT NULL DEFAULT '{}',
  is_pinned INTEGER NOT NULL DEFAULT 0,
  read_at TEXT,
  hidden_for TEXT NOT NULL DEFAULT '[]',
  moment_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_messages_relationship ON messages(relationship_id, created_at DESC);

-- Activities
CREATE TABLE activities (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  payload TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'in_progress', 'completed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_activities_relationship ON activities(relationship_id);

-- Daily challenges
CREATE TABLE daily_challenges (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  prompt TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT 'question',
  user_1_response TEXT,
  user_2_response TEXT,
  completed INTEGER NOT NULL DEFAULT 0,
  challenge_date TEXT NOT NULL DEFAULT (date('now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (relationship_id, challenge_date)
);

-- Calendar events
CREATE TABLE calendar_events (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  date_time TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT 'custom' CHECK (type IN ('date', 'anniversary', 'reminder', 'experience', 'custom')),
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'activity', 'experience')),
  description TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_calendar_relationship ON calendar_events(relationship_id, date_time);

-- Journal entries
CREATE TABLE journal_entries (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  content TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT 'reflection' CHECK (type IN ('reflection', 'gratitude', 'memory', 'emotion', 'plan')),
  is_private INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_journal_relationship ON journal_entries(relationship_id, created_at DESC);

-- Mood logs
CREATE TABLE mood_logs (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  mood TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_mood_relationship ON mood_logs(relationship_id, created_at DESC);
CREATE INDEX idx_mood_user ON mood_logs(user_id, created_at DESC);

-- Bucket list
CREATE TABLE bucket_list (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  note TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'completed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Shared goals
CREATE TABLE shared_goals (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  progress INTEGER NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Experiences (global catalog, not relationship-scoped)
CREATE TABLE experiences (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  type TEXT,
  location TEXT,
  price_range TEXT,
  external_url TEXT,
  image_url TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Saved experiences
CREATE TABLE saved_experiences (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  experience_id TEXT NOT NULL REFERENCES experiences(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (relationship_id, experience_id)
);

-- Notifications
CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  type TEXT NOT NULL,
  content TEXT NOT NULL,
  read INTEGER NOT NULL DEFAULT 0,
  push_dispatched INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_notifications_user ON notifications(user_id, read, created_at DESC);
CREATE INDEX idx_notifications_push_pending ON notifications(user_id, push_dispatched, created_at DESC)
  WHERE push_dispatched = 0;

-- Streaks
CREATE TABLE streaks (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL UNIQUE REFERENCES relationships(id) ON DELETE CASCADE,
  current_streak INTEGER NOT NULL DEFAULT 0,
  longest_streak INTEGER NOT NULL DEFAULT 0,
  last_active_date TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Wrapped stats
CREATE TABLE wrapped_stats (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  year INTEGER NOT NULL,
  moments_count INTEGER NOT NULL DEFAULT 0,
  activities_completed INTEGER NOT NULL DEFAULT 0,
  mood_summary TEXT NOT NULL DEFAULT '{}',
  highlights TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (relationship_id, year)
);

-- Analytics events
CREATE TABLE analytics_events (
  id TEXT PRIMARY KEY,
  relationship_id TEXT REFERENCES relationships(id) ON DELETE CASCADE,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  metadata TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Game sessions
CREATE TABLE game_sessions (
  id TEXT PRIMARY KEY,
  relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE,
  game_type TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
